import type { Page } from '@playwright/test';
import { Dialog, expect } from '@playwright/test';

export function getFieldRowIndex(fixture: object, fieldType: string): number {
  const rows = (fixture as any).sections[0].fieldGroups[0].rows;
  const row = rows.findIndex((r: any) => r.fields[0]?.type === fieldType);
  if (row === -1) {
    throw new Error(`Field type '${fieldType}' not found in fixture`);
  }
  return row;
}

export async function loadFixture({ page, fixture }: { page: Page; fixture: Record<string, unknown> }) {
  await page.goto('/');

  await page.setInputFiles('input[type="file"]', {
    name: 'form.json',
    mimeType: 'application/json',
    buffer: Buffer.from(JSON.stringify(fixture, null, 2)),
  });
  await page.waitForTimeout(500);
}

export async function downloadAndCompareJson({
  page,
  fixture,
  dialogDefaultName = 'formular.json',
}: {
  page: Page;
  fixture: object;
  dialogDefaultName?: string;
}) {
  // Einmaligen Listener registrieren und nach Verwendung entfernen
  const dialogHandler = async (dialog: Dialog) => {
    await dialog.accept(dialogDefaultName);
  };

  page.once('dialog', dialogHandler);

  const downloadPromise = page.waitForEvent('download', { timeout: 5000 });
  await page.getByRole('button', { name: 'JSON herunterladen' }).click();

  const download = await downloadPromise;

  let downloadedJson: unknown;
  try {
    const stream = await download.createReadStream();
    const chunks: Buffer[] = [];
    for await (const chunk of stream) {
      chunks.push(Buffer.from(chunk));
    }
    downloadedJson = JSON.parse(Buffer.concat(chunks).toString('utf-8'));
  } catch (error) {
    throw new Error(
      `Failed to parse downloaded file as JSON: ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  expect(downloadedJson).toEqual(fixture);
}

/*
 *   @param  {string} fieldType - Feldtyp, dessen Row-Index in der Fixture ermittelt wird
 */
export async function downloadAndCompareFieldRules({
  page,
  fixture,
  fieldType,
  expectedRules,
  dialogDefaultName = 'formular.json',
}: {
  page: Page;
  fixture: object;
  fieldType?: string;
  expectedRules: object[];
  dialogDefaultName?: string;
}) {
  const dialogHandler = async (dialog: Dialog) => {
    await dialog.accept(dialogDefaultName);
  };

  page.once('dialog', dialogHandler);

  const downloadPromise = page.waitForEvent('download', { timeout: 5000 });
  await page.getByRole('button', { name: 'JSON herunterladen' }).click();

  const download = await downloadPromise;

  let downloadedJson: any;
  try {
    const stream = await download.createReadStream();
    const chunks: Buffer[] = [];
    for await (const chunk of stream) {
      chunks.push(Buffer.from(chunk));
    }
    downloadedJson = JSON.parse(Buffer.concat(chunks).toString('utf-8'));
  } catch (error) {
    throw new Error(
      `Failed to parse downloaded file as JSON: ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  const index = fieldType ? getFieldRowIndex(fixture, fieldType) : 0;
  const field = downloadedJson.sections[0].fieldGroups[0].rows[index].fields[0];
  expect(field.validationRules).toEqual(expectedRules);
}
